import React from 'react';

// Mock data representing the recruitment pipeline
const recruitmentPipeline = {
  'New Applicants': [
    { id: 1, name: 'Aarav Sharma', position: 'Asst. Professor, CS' },
    { id: 2, name: 'Sanya Verma', position: 'Lab Technician, Physics' },
    { id: 3, name: 'Neha Reddy', position: 'Junior Librarian' },
  ],
  'Screening': [
    { id: 4, name: 'Rohan Mehta', position: 'Asst. Professor, CS' },
  ],
  'Interview Stage': [
    { id: 5, name: 'Priya Singh', position: 'Asst. Professor, CS' },
    { id: 6, name: 'Karan Malhotra', position: 'Lab Technician, Physics' },
  ],
  'Offer Made': [
    { id: 7, name: 'Isha Gupta', position: 'Lab Technician, Physics' },
  ],
  'Hired': [
    { id: 8, name: 'Aditya Joshi', position: 'Admissions Counselor' },
  ]
};

// We can get the titles of our columns from the keys of our pipeline object
const pipelineStages = Object.keys(recruitmentPipeline);

const RecruitmentPage = () => {
  return (
    <div className="flex flex-col h-full">
      <header className="bg-card-light dark:bg-card-dark p-4 border-b border-border-light dark:border-border-dark flex-shrink-0">
        <h1 className="text-2xl font-semibold text-text-light dark:text-text-dark">Recruitment Pipeline</h1>
      </header>

      {/* Main Kanban Board Container */}
      {/* We use flex and overflow-x-auto to make the board scroll horizontally on smaller screens */}
      <div className="flex-1 p-8 flex space-x-6 overflow-x-auto">
        {/* Map over the pipeline stages to create a column for each */}
        {pipelineStages.map(stage => (
          <div key={stage} className="bg-background-light dark:bg-background-dark rounded-lg w-72 flex-shrink-0">
            {/* Column Header */}
            <div className="p-4 border-b border-border-light dark:border-border-dark">
              <h3 className="text-sm font-semibold uppercase text-subtext-light dark:text-subtext-dark">
                {stage} ({recruitmentPipeline[stage].length})
              </h3>
            </div>
            {/* Column Body with Candidate Cards */}
            <div className="p-4 space-y-4">
              {recruitmentPipeline[stage].map(candidate => (
                <div key={candidate.id} className="bg-card-light dark:bg-card-dark p-4 rounded-md shadow-sm cursor-pointer hover:shadow-lg transition-shadow">
                  <p className="font-semibold text-text-light dark:text-text-dark">{candidate.name}</p>
                  <p className="text-xs text-subtext-light dark:text-subtext-dark mt-1">{candidate.position}</p>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default RecruitmentPage;
